{
  "findings": [
    {
      "title": "Cross-reference to non-existent section 99.3",
      "page": 25,
      "quote": "Refer to Section 99.3 for treatment compliance.",
      "severity": "major"
    },
    {
      "title": "Inconsistent pregnancy testing requirement for women with bilateral tubal ligation",
      "page": 25,
      "quote": "Pregnancy testing should be performed in women having a bilateral tubal ligation.",
      "severity": "major"
    },
    {
      "title": "Inconsistent vital signs collection relative to blood sampling",
      "page": 25,
      "quote": "When vital signs are scheduled at the same time as collection of a blood sample, the vital sign measurements should be obtained before the scheduled phlebotomy.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent vital signs collection relative to clinical laboratory assessments",
      "page": 25,
      "quote": "When clinical laboratory assessments are done the same day as vidutolimod injection, vital signs should be performed prior to collection of clinical laboratory tests.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent ECG timing relative to blood sampling",
      "page": 25,
      "quote": "When an ECG is scheduled at the same time as a blood sampling, the ECG reading should be obtained before the scheduled blood sampling.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent disease assessment frequency for long-term responders",
      "page": 26,
      "quote": "Disease assessments may be performed every 12 weeks for subjects with a response continuing more than 1 year.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent screening window for informed consent",
      "page": 26,
      "quote": "Informed consent must be provided before the initiation of screening procedures and must be obtained within 45 days prior to W1D1.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent screening window for assessments",
      "page": 26,
      "quote": "All screening assessments must be performed within 30 days prior to W1D1.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent re-screening procedure",
      "page": 26,
      "quote": "Subjects who fail screening may be screened one additional time and an ICF will need to be signed at the re-screen.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent re-screening repeat of procedures",
      "page": 26,
      "quote": "Some procedures may not need to be repeated if they were previously completed within 30 days prior to W1D1 vidutolimod injection.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent PTFU duration",
      "page": 25,
      "quote": "For an individual subject, the maximum duration of PTFU is 18 months.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent LTSFU frequency",
      "page": 25,
      "quote": "LTSFU will be conducted Q3mo (± 4 weeks) after the EOT visit or the last disease assessment date in PTFU and may occur via phone.",
      "severity": "minor"
    }
  ]
}
